"""Tree-shaken, minified vendor bundles containing only the three.js / cannon-es exports the game uses.
Scans js/*.js for THREE.X / CANNON.X (+ mergeGeometries), bundles pinned three@0.160.0 and cannon-es@0.20.0 with esbuild.
usage: python3 tools/bundle.py   ->  vendor/three.custom.min.js, vendor/cannon.custom.min.js   (then python3 tools/stamp.py)"""
import pathlib, re, subprocess, os
R = pathlib.Path(__file__).resolve().parent.parent
B = pathlib.Path(os.environ.get('BUNDLE_DIR', '/tmp/cart-vendor-build')); B.mkdir(parents=True, exist_ok=True)
src = ''.join(p.read_text(encoding='utf-8') for p in (R / 'js').rglob('*.js'))
three = sorted(set(re.findall(r'\bTHREE\.([A-Za-z_]\w*)', src))); cannon = sorted(set(re.findall(r'\bCANNON\.([A-Za-z_]\w*)', src)))
if not (B / 'node_modules' / 'three').exists():
    subprocess.run('npm init -y >/dev/null && npm i --no-audit --no-fund three@0.160.0 cannon-es@0.20.0 esbuild@0.24.0', shell=True, cwd=B, check=True)
(B / 'three-entry.js').write_text(f"export {{ {', '.join(three)} }} from 'three';\nexport {{ mergeGeometries }} from 'three/examples/jsm/utils/BufferGeometryUtils.js';\n")
(B / 'cannon-entry.js').write_text(f"export {{ {', '.join(cannon)} }} from 'cannon-es';\n")
for entry, out, lic in [('three-entry.js', 'three.custom.min.js', 'three.js r160 (MIT) — https://threejs.org'), ('cannon-entry.js', 'cannon.custom.min.js', 'cannon-es 0.20.0 (MIT) — https://github.com/pmndrs/cannon-es')]:
    subprocess.run(['npx', 'esbuild', entry, '--bundle', '--format=esm', '--minify', '--target=es2020', '--legal-comments=none',
                    f'--banner:js=/* {lic}. Generated by tools/bundle.py — only the exports the game uses. */', f'--outfile={R / "vendor" / out}'], cwd=B, check=True)
# supabase-js: ESM bundle of createClient only (lazy-loaded by js/account.js)
if not (B / 'node_modules' / '@supabase' / 'supabase-js').exists():
    subprocess.run('npm i --no-audit --no-fund @supabase/supabase-js@2.109.0', shell=True, cwd=B, check=True)
(B / 'supabase-entry.js').write_text("export { createClient } from '@supabase/supabase-js';\n")
subprocess.run(['npx', 'esbuild', 'supabase-entry.js', '--bundle', '--format=esm', '--minify', '--target=es2020', '--legal-comments=none', '--platform=browser',
                '--banner:js=/* @supabase/supabase-js 2.109.0 (MIT) — https://github.com/supabase/supabase-js. ESM bundle generated by tools/bundle.py (createClient only). */', f'--outfile={R / "vendor" / "supabase.mjs"}'], cwd=B, check=True)
print('three exports', len(three), 'cannon exports', len(cannon))
